// Modelo de Gemini. Cámbialo aquí si quieres otro (p. ej. 'gemini-2.5-flash-lite', más barato).
const MODEL = 'gemini-2.5-flash';

const item = $input.first();
const body = item.json.body || {};
const binary = item.binary || {};
const key = Object.keys(binary)[0];
if (!key) throw new Error('No ha llegado ningún archivo (campo "file").');

const buffer = await this.helpers.getBinaryDataBuffer(0, key);
const mimeType = binary[key].mimeType || 'image/png';

// Campos a buscar: [{ clave, valor }]. Acepta el formato nuevo ("campos", JSON)
// y el antiguo ("listaContenidoBuscar": '"clave":"desc","clave2":"desc2"').
let campos = [];
if (body.campos) {
  campos = typeof body.campos === 'string' ? JSON.parse(body.campos) : body.campos;
} else if (body.listaContenidoBuscar) {
  const raw = Array.isArray(body.listaContenidoBuscar) ? body.listaContenidoBuscar.join(',') : String(body.listaContenidoBuscar);
  campos = Object.entries(JSON.parse('{' + raw + '}')).map(([clave, valor]) => ({ clave, valor }));
}
campos = (Array.isArray(campos) ? campos : []).filter(c => c && c.clave);
if (!campos.length) throw new Error('No ha llegado ningún campo a buscar.');

const prompt = [
  'Eres un sistema de OCR. Lee el documento de la imagen.',
  '1. En "campos", devuelve una entrada por cada clave de la lista de abajo, con el valor tal y como aparece escrito en el documento y la caja donde aparece. Si el dato no está en el documento, valor = "" y sin caja. No inventes ni calcules valores.',
  '2. En "bloques", devuelve todos los bloques de texto del documento (líneas o párrafos cortos) en orden de lectura, cada uno con su texto exacto y su caja. Separa en bloques distintos los textos que estén en celdas o columnas distintas.',
  'Las cajas van en box_2d = [ymin, xmin, ymax, xmax], normalizadas de 0 a 1000 respecto a la imagen.',
  '',
  'Campos a buscar (clave: descripción):',
  ...campos.map(c => `- ${c.clave}: ${c.valor || ''}`),
].join('\n');

const box = { type: 'ARRAY', items: { type: 'INTEGER' } };
const peticion = {
  contents: [{
    role: 'user',
    parts: [
      { inline_data: { mime_type: mimeType, data: buffer.toString('base64') } },
      { text: prompt },
    ],
  }],
  generationConfig: {
    temperature: 0,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        campos: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: { clave: { type: 'STRING' }, valor: { type: 'STRING' }, box_2d: box },
            required: ['clave', 'valor'],
          },
        },
        bloques: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: { texto: { type: 'STRING' }, box_2d: box },
            required: ['texto', 'box_2d'],
          },
        },
      },
      required: ['campos', 'bloques'],
    },
    // Sin "razonamiento": más rápido y más barato. Quítalo si cambias a un modelo que no lo admita.
    thinkingConfig: { thinkingBudget: 0 },
  },
};

return [{ json: { model: MODEL, campos, peticion } }];

// Convierte la respuesta de Gemini al formato que ya usa el frontend (el de Document AI):
// { buscarCampos: [{ clave: valor }], pages: [{ blocks: [{ type, text, boundingPoly }] }] }
const prep = $('Preparar petición').first().json;
const res = $input.first().json;

const text = (res?.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  const motivo = res?.candidates?.[0]?.finishReason || res?.promptFeedback?.blockReason || 'desconocido';
  throw new Error(`Gemini no devolvió JSON válido (motivo: ${motivo}): ${text.slice(0, 300)}`);
}

const toPoly = (b) => {
  if (!Array.isArray(b) || b.length !== 4) return null;
  const [ymin, xmin, ymax, xmax] = b.map(n => Math.min(1000, Math.max(0, Number(n) || 0)) / 1000);
  if (xmax <= xmin || ymax <= ymin) return null;
  return {
    normalizedVertices: [
      { x: xmin, y: ymin }, { x: xmax, y: ymin },
      { x: xmax, y: ymax }, { x: xmin, y: ymax },
    ],
  };
};

const valores = {};
prep.campos.forEach(c => { valores[c.clave] = ''; });

const blocks = [];
const textos = new Set();
(parsed.bloques || []).forEach(b => {
  const t = String(b?.texto ?? '').trim();
  const poly = toPoly(b?.box_2d);
  if (!t || !poly) return;
  blocks.push({ type: 'PARAGRAPH', text: t, boundingPoly: poly });
  textos.add(t);
});

(parsed.campos || []).forEach(c => {
  if (!c || !Object.prototype.hasOwnProperty.call(valores, c.clave)) return;
  const v = String(c.valor ?? '').trim();
  valores[c.clave] = v;
  // Que cada valor encontrado tenga su caja en el panel aunque no venga entre los bloques
  const poly = toPoly(c.box_2d);
  if (v && poly && !textos.has(v)) {
    blocks.push({ type: 'PARAGRAPH', text: v, boundingPoly: poly });
    textos.add(v);
  }
});

return [{
  json: {
    buscarCampos: [valores],
    pages: [{ blocks }],
    modelo: prep.model,
    uso: res.usageMetadata || null,
  },
}];
